/*
 * NeolyxOS - NXIcon pack: the system icon set linked into the desktop
 *
 * The boot image carries no files the desktop can open, so every icon
 * the shell needs ships inside the desktop image as NXIB bitmaps
 * (System/Desktop/Icons/<name>.nxi, linked by shell/nxicon_pack.S and
 * generated by tools/build_icon_pack.py from
 * resources/icons/pack/iconpack.manifest).
 *
 * Names are stable lookups: "app-files", "folder-documents",
 * "device-external", ... Every entry is validated once at init; an entry
 * that fails validation is never returned.
 *
 * Copyright (c) 2025-2026 KetiveeAI
 */

#ifndef NXICON_PACK_H
#define NXICON_PACK_H

#include <stdint.h>
#include "nxcanvas.h"

#define NXICON_PACK_NAME_MAX 48

/* A validated icon: straight-alpha RGBA8, rows packed (stride = w * 4). */
typedef struct {
    const char    *name;
    const uint8_t *rgba;
    int32_t        width;
    int32_t        height;
} nxicon_pack_image_t;

/*
 * Validate every linked icon. Returns the number of valid icons and
 * stores the number rejected (bad header or size) in *rejected when
 * non-NULL. Safe to call more than once; lookups validate lazily if this
 * was never called.
 */
int nxicon_pack_init(int *rejected);

/* Number of linked icons (valid or not). */
int nxicon_pack_count(void);

/*
 * Find an icon by exact name. Returns 0 and fills *out on success,
 * -1 if the name is NULL/too long, unknown, or the icon failed
 * validation.
 */
int nxicon_pack_find(const char *name, nxicon_pack_image_t *out);

/*
 * Draw a pack icon scaled into a size x size square at (x, y). Returns
 * NXC_ERR_INVALID_ARG for bad arguments and NXC_ERR_NOT_FOUND when the
 * icon is missing, so callers can fall back to something else.
 */
nxc_status_t nxicon_pack_draw(nxc_canvas_t *c, const char *name, float x, float y,
                              float size, uint8_t alpha);

/*
 * Pack icon name for a directory, from its last path component
 * ("Documents", "Downloads", "Music", ...). Unknown folders give
 * "folder-generic"; never returns NULL.
 */
const char *nxicon_pack_folder_name(const char *dir_path);

#endif /* NXICON_PACK_H */
